select id,cn_name, eg_name, flow_id,track_map_id,platform,api_name,touch_moment,env,status,fail_reason,
 is_deleted,create_man ,create_man_id,create_date ,modify_man ,modify_man_id,modify_date
from track_event a

    and a.id = #{id}
    and a.track_map_id = #{trackMapId}
    and a.cn_name = #{cnName}
    and a.eg_name = #{egName}
    and a.is_deleted=false

